bool _isHebrewMark(int codeUnit) {
  // All Hebrew pointing/cantillation, including maqaf, for loose matching.
  return codeUnit >= 0x0591 && codeUnit <= 0x05C7;
}

bool _isApostropheLike(int codeUnit) {
  // Strong's transliterations use modifier letters like ʼ and ʽ.
  return codeUnit == 0x0027 || // '
      codeUnit == 0x02BC || // ʼ
      codeUnit == 0x02BD || // ʽ
      codeUnit == 0x02BF || // ʿ
      codeUnit == 0x02BE || // ʾ
      codeUnit == 0x2019 || // ’
      codeUnit == 0x0060; // `
}

/// Folds text for search matching: lowercase, Hebrew pointing stripped,
/// Greek/Latin diacritics reduced to base letters, apostrophes dropped.
String foldForSearch(String text) {
  final buffer = StringBuffer();
  for (final codeUnit in text.toLowerCase().codeUnits) {
    if (_isHebrewMark(codeUnit) || _isApostropheLike(codeUnit)) {
      continue;
    }
    buffer.writeCharCode(kDiacriticFoldMap[codeUnit] ?? codeUnit);
  }
  return buffer.toString().trim();
}
